// TH15 v1.00b Stage 6 道中 MainSub01 -> Phantom01 / Phantom01_at
// Source: st06.ecl.txt:606-625 (spawn schedule), 983-1004 (enemy), 1006-1043 (fire loop)
// 合成外壳: 章节入口/章节状态/刷怪门控删除; 普通掉落、出生动画与音效省略(已批准).
// 镜像: enmCreateM 子镜像按指令写入点换算 ABS 速度与出生 x; REL 圆周按规则书不随镜像翻转.

const TIME_LIMIT: int = 1424;
const OPENING_BUFFER: int = 120;

// TH15 弹型合成映射: 源 etSprite type18 = TH15_BIG_BALL (基础半径已核一致)
const TH15_BIG_BALL: int = 640;
const BULLET_COLOR: int = 2;

const PHANTOM_HP: int = 120;
const PHANTOM_SCORE: int = 1000;

// Phantom01_at (st06:1006-1043)
// diffI($A,1,3,5,5); !E/!N wait RAND%180, !H RAND%120, !LO RAND%90;
// 速度 !E/!N 4.0, !H 5.0, !LO 6.0; 每轮 etNew/etAim(0)/etSprite(18,2)/etCount(1,1)/etOn.
// etEx type=2 ANIM (a=1) 仅出生动画, 按已批准口径省略.
async sub phantom_at() {
    var rank: int = global(GVAR_RANK);
    var shots: int = 5;
    if rank == 0 { shots = 1; }
    else if rank == 1 { shots = 3; }
    for i in 0..shots {
        var wait_frames: int = 0;
        if rank <= 1 { wait_frames = rand(180); }
        else if rank == 2 { wait_frames = rand(120); }
        else { wait_frames = rand(90); }
        wait(wait_frames);
        var spd: fx = 6fx;
        if rank <= 1 { spd = 4fx; }
        else if rank == 2 { spd = 5fx; }
        _ = fire(TH15_BIG_BALL, BULLET_COLOR, $self_x, $self_y, spd, aim_player(), none, none);
    }
}

// Phantom01 (st06:983-1004)
// setHurtbox(28,28) -> r14; setHitbox(16,16) -> r8 (普通圆形分支取第一值*0.5).
// 异步 at 任务与主运动同帧启动; 运动由两段合成:
//   ABS: moveVel(pi,3) 60帧, 再 moveVelTime(120,mode0,pi/4,2)
//   REL: moveCircleRel(%RANDRAD, 0.034906585=2deg/帧, r=0) 后 moveCircleRelTime(80,mode0,
//        omega保留, r=8, d=0), 半径0->8线性, 相位持续累加.
// 目标无 REL 层, 逐帧用 move_to(0,...) 写合成位置; side=+1 右侧(出生x=208), -1 镜像左侧.
async sub phantom(side: int) {
    set_invuln(65535);
    set_hurtbox(14fx);
    set_hitbox(8fx);
    spawn phantom_at();
    var bx: fx = $self_x;
    var by: fx = $self_y;
    var theta: angle = rand(65536) as angle;   // %RANDRAD 全域 [-pi,pi)
    var r: fx = 0fx;
    var ax: fx = 0fx;                           // ABS 位移(右侧参考系)
    var ay: fx = 0fx;
    var t: int = 0;
    loop {
        var ox: fx = r * cos(theta);
        var oy: fx = r * sin(theta);
        move_to(0, bx + (side as fx) * ax + ox, by + ay + oy, EASE_LINEAR);
        wait(1);
        t = t + 1;
        // 第 t 次运动 tick: 先推进角/速插值再积分
        var a: angle = 180deg;
        var s: fx = 3fx;
        if t > 60 {
            if t <= 180 {
                a = (32768 - 24576 * (t - 60) / 120) as angle;   // 180deg -> 45deg
                s = 3fx - (t - 60) as fx / 120fx;                // 3 -> 2
            } else {
                a = 45deg;
                s = 2fx;
            }
        }
        ax = ax + s * cos(a);
        ay = ay + s * sin(a);
        if t <= 80 {
            r = 8fx * (t as fx) / 80fx;         // CircleRelTime r: 0 -> 8 linear
        }
        theta = theta + 2deg;                    // omega = 0.034906585 rad
    }
}

// MainSub01 (st06:606-625): $A=$B=32, 右组先每5帧一只, 再镜像左组每5帧一只;
// enmCreate("Phantom01",208,128+RANDF2*32,120,1000,1)
async sub pattern() {
    wait(OPENING_BUFFER);
    for i in 0..32 {
        var y: fx = 128fx + ((rand(65536) - 32768) as fx) * 0.0009765625fx;
        _ = spawn_enemy(208fx, y, PHANTOM_HP, 0, PHANTOM_SCORE, 0, phantom(1));
        wait(5);
    }
    for j in 0..32 {
        var y2: fx = 128fx + ((rand(65536) - 32768) as fx) * 0.0009765625fx;
        _ = spawn_enemy(-208fx, y2, PHANTOM_HP, 0, PHANTOM_SCORE, 0, phantom(-1));
        wait(5);
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
